// Run Context: one shape for every run, launched or scheduled.
// sd.launch.recordId  = the Hub Automations row this run was launched from ('' on a schedule)
// sd.launch.trigger   = 'form' when launched from the Hub, 'schedule' otherwise
// sd.launch.clientFilter = the launch row's Client link (one record id) to scope the run to one client; '' = all clients
const sd = $getWorkflowStaticData('global');
let launch = null;
try { const r = $('Fetch Launch Record').first().json; if (r && r.id) launch = r; } catch (e) {}
const f = (launch && launch.fields) || launch || {};
const cl = Array.isArray(f.Client) && f.Client.length ? f.Client[0] : '';
const clientFilter = (cl && typeof cl === 'object') ? String(cl.id || '') : String(cl || '');
sd.launch = { recordId: launch ? String(launch.id) : '', trigger: launch ? 'form' : 'schedule', clientFilter, startedAt: $now.toMillis() };
sd.results = []; sd.updates = []; sd.failed = [];
return [{ json: Object.assign({}, sd.launch) }];

// Decide: the standard, applied once over every campaign that carries a Stage.
// Reads only what the Hub already holds: the Campaigns rows the syncs wrote at 07:00, and the
// newest deploy row per campaign (Left in View, written by the deploy doors). Never a platform.
// Writes nothing here: it plans the Stage moves (Test to Scale, Test to Killed, never Run) and
// the per-client report blocks into static data; Update Stage and Build Messages consume them.
// The numbers below are the card's standard block (managers/Campaigns-Manager/card.json); a change
// there is a change here, in the same commit.
const STANDARD = {
  stageTotal: { Test: 1000, Scale: 3000, Run: null },
  line: { Test: 1000, Scale: 3000 },
  positives: { Email: 1, LinkedIn: 3 },
  inPlayStages: ['Test', 'Scale', 'Run'],
  notInPlayStatus: ['PAUSED', 'DRAFT', 'STOPPED'],
};
const sd = $getWorkflowStaticData('global');
const launch = sd.launch || {};
const cf = String(launch.clientFilter || '');
const nm = v => (v && typeof v === 'object') ? String(v.name || '') : String(v || '');
const num = v => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
const items = name => { try { return $(name).all().map(i => i.json).filter(j => j && j.id); } catch (e) { return []; } };

// Clients: id -> name
const clientName = {};
for (const j of items('Get Clients')) { const f = j.fields || j; clientName[j.id] = String(f['Client'] || j.id); }

// Newest deploy row per campaign id (Target on a scheduled launch row is the campaign id).
const newestDeploy = {};
for (const j of items('Get Deploy Rows')) {
  const f = j.fields || j;
  const target = String(f['Target'] || '').trim();
  if (!target) continue;
  const at = Date.parse(f['Run at'] || '') || 0;
  if (!newestDeploy[target] || at > newestDeploy[target].at) {
    const liv = f['Left in View'];
    newestDeploy[target] = { at, leftInView: (liv === undefined || liv === null || liv === '') ? null : num(liv), runAt: f['Run at'] || '' };
  }
}

// Campaigns with a Stage, scoped by the client filter on a launched run.
const camps = [];
for (const j of items('Get Campaigns')) {
  const f = j.fields || j;
  const clientIds = (Array.isArray(f['Client']) ? f['Client'] : []).map(c => (c && typeof c === 'object') ? String(c.id || '') : String(c || '')).filter(Boolean);
  if (cf && !clientIds.includes(cf)) continue;
  const stage = nm(f['Stage']);
  if (!stage || stage === 'Killed') continue;
  const channel = nm(f['Channel']);
  camps.push({
    rid: j.id,
    name: String(f['Campaign'] || j.id),
    campaignId: String(f['Campaign ID'] || '').trim(),
    sender: nm(f['Sequencer']) || '?',
    lane: channel === 'Email' ? 'Email' : 'LinkedIn',
    status: nm(f['Status']),
    stage,
    leads: num(f['Leads']),
    contacted: num(f['Contacted']),
    positives: num(f['Positive Replies (PV)']),
    liveView: String(f['Live View ID'] || '').trim(),
    clientId: clientIds[0] || '',
    lastSent: f['Last Sent'] || '',
  });
}
sd.scope = cf ? (camps.length ? 'one client (on demand)' : 'client filter matched no managed campaign') : 'all clients';
sd.managed = camps.length;

// Shared views: two in-play campaigns drinking from one Live View ID.
const inPlay = c => STANDARD.inPlayStages.includes(c.stage) && !STANDARD.notInPlayStatus.includes(c.status);
const viewUse = {};
for (const c of camps) if (inPlay(c) && c.liveView) viewUse[c.liveView] = (viewUse[c.liveView] || 0) + 1;

const byClient = {};
const updates = [];
for (const c of camps) {
  const key = c.clientId || '(no client)';
  const R = byClient[key] || (byClient[key] = { clientRecId: c.clientId, client: clientName[c.clientId] || (c.clientId ? c.clientId : '(no client)'), testProgress: [], testReady: [], scaleProgress: [], scaleReady: [], run: [], paused: [], moved: [], failed: [] });
  c.perPositive = c.positives ? Math.round(c.contacted / c.positives) : null;
  c.tags = [];
  if (!inPlay(c)) {
    if (c.status === 'PAUSED') R.paused.push(c);
    continue;
  }
  if (!c.liveView) c.tags.push('NO VIEW');
  else if (viewUse[c.liveView] > 1) c.tags.push('SHARED VIEW');
  const d = c.campaignId ? newestDeploy[c.campaignId] : null;
  if (d && d.leftInView === 0) c.tags.push('DRY since ' + String(d.runAt).slice(0, 10));
  if (c.lane === 'LinkedIn') c.tags.push('LINKEDIN');
  const need = STANDARD.positives[c.lane];
  if (c.stage === 'Test') {
    if (c.contacted >= STANDARD.line.Test) {
      if (c.positives >= need) { c.verdict = 'moved to Scale'; updates.push({ id: c.rid, Stage: 'Scale', name: c.name, client: R.client }); }
      else { c.verdict = 'killed'; updates.push({ id: c.rid, Stage: 'Killed', name: c.name, client: R.client }); }
      R.testReady.push(c); R.moved.push(c);
    } else R.testProgress.push(c);
  } else if (c.stage === 'Scale') {
    if (c.contacted >= STANDARD.line.Scale) R.scaleReady.push(c); else R.scaleProgress.push(c);
  } else R.run.push(c);
}
for (const k of Object.keys(byClient)) byClient[k].scaleReady.sort((a, b) => (a.perPositive || 1e9) - (b.perPositive || 1e9));
sd.results = Object.keys(byClient).map(k => byClient[k]).sort((a, b) => a.client.localeCompare(b.client));
sd.updates = updates;
sd.standard = STANDARD;
if (!updates.length) return [{ json: { _none: true } }];
return updates.map(u => ({ json: { id: u.id, Stage: u.Stage } }));

// Collect Updates: the Stage writes came back; a failed write is an error on the run, named by
// campaign, and the report still says what the standard decided. Emits one item so the chain
// continues into the messages whether there were updates or none.
const sd = $getWorkflowStaticData('global');
const updates = sd.updates || [];
let results = [];
try { results = $('Update Stage').all().map(i => i.json || {}); } catch (e) {}
sd.updated = 0;
updates.forEach((u, i) => {
  const r = results[i] || {};
  if (r.error || (r.id && r.id !== u.id)) sd.failed.push(u.client + ': could not set Stage ' + u.Stage + ' on "' + u.name + '": ' + JSON.stringify(r.error || r).slice(0, 160));
  else sd.updated++;
});
return [{ json: { updated: sd.updated, planned: updates.length } }];

// Build Messages: one Slack message per client, the same shape every day. Bold stage headers,
// code blocks with aligned columns, tags at the end of a line. Empty sections are left out; a
// client with nothing in play gets no message.
const sd = $getWorkflowStaticData('global');
const CHANNEL = 'C0B8Q745KT8'; // #flowroots-campaigns
const S = sd.standard || { line: { Test: 1000, Scale: 3000 } };
const fmt = v => Number(v || 0).toLocaleString('en-US');
const pad = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s.padEnd(n); };
const rpad = (s, n) => String(s == null ? '' : s).padStart(n);
const tags = c => c.tags && c.tags.length ? '  [' + c.tags.join('] [') + ']' : '';
const per = c => c.perPositive ? '1 per ' + fmt(c.perPositive) : '';

const NAME = 58;
const line = (c, over) => pad(c.name, NAME) + '  ' + pad(c.sender, 11) + rpad(fmt(c.contacted) + (over ? ' / ' + fmt(over) : ''), 15) + rpad(fmt(c.positives), 5) + '  ' + pad(per(c), 12) + tags(c);
const readyLine = c => pad(c.name, NAME) + '  ' + pad(c.sender, 11) + rpad(fmt(c.contacted), 15) + rpad(fmt(c.positives), 5) + '  ' + pad(per(c), 12) + (c.verdict ? '  ' + c.verdict : '') + tags(c);
const block = rows => '```\n' + rows.join('\n') + '\n```';
const header = pad('campaign', NAME) + '  ' + pad('sender', 11) + rpad('contacted', 15) + rpad('pos', 5) + '  ' + pad('rate', 12);

const today = new Date().toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'Asia/Jerusalem' });
const out = [];
for (const R of sd.results || []) {
  const parts = ['*' + R.client.toUpperCase() + ' · campaigns · ' + today + '*'];
  if (R.testProgress.length) parts.push('*TEST · in progress*', block([header].concat(R.testProgress.map(c => line(c, S.line.Test)))));
  if (R.testReady.length) parts.push('*TEST · ready*', block(R.testReady.map(readyLine)));
  if (R.scaleProgress.length) parts.push('*SCALE · in progress*', block([header].concat(R.scaleProgress.map(c => line(c, S.line.Scale)))));
  if (R.scaleReady.length) parts.push('*SCALE · ready, ranked*', block([header].concat(R.scaleReady.map(readyLine))));
  if (R.run.length) parts.push('*RUN*', block([header].concat(R.run.map(c => line(c)))));
  if (R.paused.length) parts.push('*PAUSED BY HAND*', block(R.paused.map(c => pad(c.name, NAME) + '  ' + pad(c.sender, 11) + rpad(fmt(c.contacted), 15) + rpad(fmt(c.positives), 5) + '  ' + pad(per(c), 12) + '  set Killed or unpause')));
  if (parts.length === 1) continue;
  R.messageLines = parts.length - 1;
  out.push({ json: { channel: CHANNEL, text: parts.join('\n'), client: R.client } });
}
sd.messages = out.length;
if (!out.length) return [{ json: { _none: true } }];
return out;

// Build Run Log: the run's one Hub row. Status computed from failed[], skips separate, the
// Description a human reads at a glance: scope, per client what is in play and what moved.
const sd = $getWorkflowStaticData('global');
const launch = sd.launch || {};
const results = sd.results || [];
const failed = (sd.failed || []).slice();
const updates = sd.updates || [];

let posted = 0;
try {
  for (const it of $('Post to Slack').all()) { const j = it.json || {}; if (j._none) continue; if (j.error) failed.push('Slack post failed: ' + JSON.stringify(j.error).slice(0, 160)); else if (j.ok || j.ts || j.message) posted++; }
} catch (e) {}

const lines = results.map(R => {
  const inPlay = R.testProgress.length + R.testReady.length + R.scaleProgress.length + R.scaleReady.length + R.run.length;
  const moved = R.moved.map(c => '"' + c.name + '" ' + c.verdict).join(', ');
  const dry = [].concat(R.testProgress, R.scaleProgress, R.run).filter(c => (c.tags || []).some(t => t.indexOf('DRY') === 0 || t === 'NO VIEW' || t === 'SHARED VIEW')).map(c => '"' + c.name + '" ' + c.tags.filter(t => t !== 'LINKEDIN').join(', ')).join('; ');
  return '- **' + R.client + ':** ' + inPlay + ' in play (Test ' + (R.testProgress.length + R.testReady.length) + ', Scale ' + (R.scaleProgress.length + R.scaleReady.length) + ', Run ' + R.run.length + '), ' + R.scaleReady.length + ' ready to judge, ' + R.paused.length + ' paused by hand' + (moved ? '. Moved: ' + moved : '') + (dry ? '. Flags: ' + dry : '');
});

const parts = [
  '**' + (sd.managed || 0) + ' managed campaign(s) across ' + results.length + ' client(s), ' + (sd.updated || 0) + ' stage move(s), ' + posted + ' message(s) posted**',
  '**Scope:** ' + (sd.scope || 'all clients'),
  '**Slack:** ' + (posted ? posted + ' message(s) to #flowroots-campaigns' : 'nothing posted'),
].concat(lines);
if (!results.length) parts.push('**Skipped (1, ' + (launch.clientFilter ? 'client filter matched no managed campaign' : 'no campaign carries a Stage') + ')**');
if (failed.length) parts.push('', '**Errors**', ...failed.map(f => '- ' + f));

const row = {
  'Automation': 'Campaigns Manager',
  'Status': failed.length ? 'Succeeded with errors' : 'Succeeded',
  'Run at': $now.toISO(),
  'Records In': sd.managed || 0,
  'Records Out': sd.updated || 0,
  'Errors': failed.length,
  'Target': 'Campaigns',
  'Trigger': launch.trigger || 'schedule',
  'Execution ID': String($execution.id),
  'Execution Link': 'https://n8n.flowroots.com/workflow/' + $workflow.id + '/executions/' + $execution.id,
  'Duration s': Math.round(($now.toMillis() - (launch.startedAt || $now.toMillis())) / 1000),
  'Description': parts.join('\n'),
};
// Client is attached only when the run served exactly one client; never an empty link array.
if (launch.clientFilter) row['Client'] = [launch.clientFilter];
return [{ json: row }];
